#!/usr/bin/env bash
# СУДИТ: scripts/backlog-recheck.sh
# СУД: только в рабочем дереве
# (D1295, 15 ноября 2026) «Проверки» D1009 и D411 судят неотслеживаемый кэш карты живой копии (`mcp-server/visualization/`
#  под .gitignore): в снимке файла нет, и проба красна по построению — прибор звал её «рамка не собралась».
# (предмет словами: «Проверки» семи закрытых пунктов архива — D477, D380, D411, D272, D326, D1156, D1009 — через
#  scripts/backlog-recheck.sh --archive; исполнитель и правило «красная засчитывается при названном откате» — у probe_D1196)
# probe_D1242 — у каждого из семи красных живого прогона архива 3 ноября 2026 названо: «Проверка» держится на нынешнем
#   дереве (гнилая починена) либо её откат назван открытым пунктом («откат D<N>» в заголовке). Своей копии исполнения нет:
#   тем же исполнителем судят свои перечни probe_D1196 и probe_D1197 (ручка PROBE_ARCHIVE_IDS).
# Код: 0 — держатся либо откат назван; 1 — красна без пункта (названа); 2 — исполнитель не ответил.
R="${CLAUDSOUL_REPO:-$(cd "$(dirname "$0")/../../.." && pwd)}"
P="$R/hooks/tests/fixtures/probe_D1196.sh"
[ -f "$P" ] || { echo "нет исполнителя $P"; exit 2; }
PROBE_ARCHIVE_IDS="D477 D380 D411 D272 D326 D1156 D1009" CLAUDSOUL_REPO="$R" bash "$P"
